    "Submit Refresh re-fetches GET …/indexer/health. The reconcile-reports, observability, and admin hub links navigate in-page only (no refresh).",
  admin_indexer_ops_heading: "Internal indexer & reconcile (ops)",
  admin_indexer_ops_hint:
    "Write paths are not invoked from this Admin page. On a trusted host (job runner or curl against localhost / private network):\n• POST /api/v1/internal/indexer-tick — advance indexing / projections\n• POST /api/v1/internal/indexer-replay — replay event_log → orders_projection\n• POST /api/v1/internal/indexer-reconcile — compare orders ↔ orders_projection; JSON may include persist, chain_id, rpc_escrow_samples (1–10); 200 body includes root issues_total / projection_reconcile_clean (same as stats) for jq\n• GET /api/v1/internal/indexer-status — checkpoint / lag snapshot; optional ?live_reconcile=1 for live orders↔projection reconcile block\n• bash scripts/indexer-reconcile-probe.sh or internal-indexer-ops.sh probe — exit 0 iff live projection_reconcile_clean (jq + secret required)\n• bash scripts/internal-indexer-ops.sh status|status --live-reconcile|probe|recover|evidence|evidence-bundle|tick|replay|reconcile — recover → indexer-reorg-recovery.sh; evidence-bundle writes manifest + optional zip (RUNBOOK §2.55)\nIf INTERNAL_API_SECRET is configured, send header X-Internal-Api-Secret.\nUse this UI for read-only health and reports; curl templates: ops/RUNBOOK.md §2.55. Spec: docs/spec/04-后端与API.md §3.4 (internal). Full-chain / evidence scope: docs/spec/110-阶段开发链上索引器与事件同步器.md.",
  admin_indexer_ops_projection_sync_note:
    "After POST /api/v1/internal/indexer-reorg-rewind (or auto-rewind on tick) with INDEXER_REORG_SYNC_ORDERS_FROM_PROJECTION_AFTER_REWIND=1, the JSON body may include orders_table_projection_sync: clear_terminal_orphan_escrow_enabled mirrors INDEXER_REORG_SYNC_CLEAR_ORPHAN_ESCROW_TERMINAL for audit; cleared_orphan_escrow_pre_funded clears orphan escrow_address on draft|created|accepted when no projection row exists; cleared_orphan_escrow_terminal_no_projection (when that env is 1) does the same for completed|disputed|refunded|partially_refunded|slashed|cancelled; otherwise skipped_no_projection_non_escrowed_with_escrow counts rows left for manual review. Full-table per-chain rollback of orders remains Target (no chain_id column yet; see docs/spec/110 §3.1.4). See docs/spec/110 §3.1.3.",

