  traveltrust_link_tokenSystem: "Token layers",
  traveltrust_legacy_faq_title: "FAQ",
  traveltrust_legacy_faq_intro:
    "Plain-language answers; for legal or jurisdiction-specific wording, follow 08-4 and governance sign-off when published.",
  traveltrust_legacy_faq_q1: "Is trip money safe?",
  traveltrust_legacy_faq_a1:
    "Travel orders use on-chain Escrow with allowlisted stablecoins where the deployment is configured. You keep wallet custody; the app orchestrates signing. Exact non-custody boundaries are in 08-4 and help center.",
  traveltrust_legacy_faq_q2: "Do I need a special token to book a trip?",
  traveltrust_legacy_faq_a2:
    "The live product path settles in allowlisted stablecoins (e.g. USDC) on EVM L2. TTG, Country Pool, or FeeRouter extensions are documented as Target / roadmap in 82–84 and must not be read as replacing trip settlement currency.",
  traveltrust_legacy_faq_q3: "How does settlement and release work?",
  traveltrust_legacy_faq_a3:
    "Flow follows 01 / 53: bilateral confirmation, Escrow funding, off-chain trip completion confirmation, rating where applicable, then on-chain release when conditions are met—not a single “done” button that equals payout.",
  traveltrust_legacy_faq_q4: "Is a given chain or feature already live?",
  traveltrust_legacy_faq_a4:
    "It depends on the environment you use. Check runtime config and GET /meta for your deployment; this landing page is narrative, not a live network status board.",
  traveltrust_legacy_faq_q5: "How are disputes handled?",
  traveltrust_legacy_faq_a5:
    "Disputes align with 01 / 03: structured paths and, where configured, human resolution followed by contract execution. See /disputes and /help for product entry points.",
  traveltrust_legacy_faq_visual_note:
    "Any future motion graphics on this page are illustrative; they are not real-time on-chain trade confirmations.",
