  governance_impact_timeline_queued_operation: "Timelock: operation id seen in projection (queued)",
  governance_impact_timeline_operation_pending: "Timelock: operation id not seen yet (not queued or indexer lag)",
  governance_impact_exec_payload_heading: "Post-pass execution payload (API boundary)",
  governance_impact_exec_payload_body:
    "`GET …/governance/proposals/:id` does **not** include **`targets[]` / `values[]` / `calldatas[]`** for the Governor proposal; this page **cannot** decode a specific Treasury spend or FeeRouter call from HTTP alone. Verify queued operations and Timelock in a block explorer; when aligning with **89 / §4.5 governance-token spec**, treat chain state as SSOT.",
  governance_impact_voting_power_snapshot_heading: "My voting power at snapshot (read-only)",
  governance_impact_voting_power_snapshot_note:
    "JSON from the same **`GovernanceVotesToken.getPastVotes`-style `eth_call`** as the API; display replaces legacy literals with **governance_token** wording without changing wire fields.",
  governance_b090_onchain_chain_id_label: "chain_id (from list or meta)",
  governance_b090_onchain_governor_label: "governor_address (GET /meta.chain.contracts when available)",
  governance_b090_onchain_governor_unavailable: "Governor address not present in GET /meta (configure FEE_ROUTER / chain or open meta in another tab).",
